/**
 * Lightweight Standalone WebGL 3D CAD Viewer Engine (Three.js Compatible)
 * Supports 3D Mesh Rendering, Ambient/Directional Lighting, Mouse Drag Rotation, and Zooming.
 */
(function (global) {
    "use strict";

    function OQC3DViewer(containerId, options) {
        options = options || {};
        var container = document.getElementById(containerId);
        if (!container) return;

        // Clear container
        container.innerHTML = '';
        container.style.position = 'relative';
        container.style.overflow = 'hidden';

        // Canvas element
        var canvas = document.createElement('canvas');
        canvas.style.width = '100%';
        canvas.style.height = '100%';
        canvas.style.display = 'block';
        container.appendChild(canvas);

        var gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
        if (!gl) {
            container.innerHTML = '<div style="padding:20px;color:#f87171;text-align:center;">WebGL tidak didukung oleh browser Anda.</div>';
            return;
        }

        // Theme Configurations (Light Gray, Dark Slate, Clean White)
        var THEMES = {
            light: {
                key: 'light',
                label: '☀️ Light Gray',
                clearColor: [0.94, 0.96, 0.98, 1.0], // #f1f5f9
                wireframeColor: [0.1, 0.4, 0.9],
                modelColor: [0.15, 0.45, 0.92],
                btnBg: 'rgba(255, 255, 255, 0.92)',
                btnColor: '#1e293b',
                btnBorder: '#cbd5e1',
                footerBg: 'rgba(241, 245, 249, 0.92)',
                footerColor: '#334155',
                footerBorder: 'rgba(203, 213, 225, 0.8)'
            },
            slate: {
                key: 'slate',
                label: '🌙 Dark Slate',
                clearColor: [0.06, 0.1, 0.17, 1.0], // #0f172a
                wireframeColor: [0.2, 0.6, 1.0],
                modelColor: [0.23, 0.51, 0.96],
                btnBg: 'rgba(15, 23, 42, 0.85)',
                btnColor: '#ffffff',
                btnBorder: '#334155',
                footerBg: 'rgba(15, 23, 42, 0.85)',
                footerColor: '#94a3b8',
                footerBorder: 'rgba(51, 65, 85, 0.5)'
            },
            white: {
                key: 'white',
                label: '📄 Clean White',
                clearColor: [1.0, 1.0, 1.0, 1.0], // #ffffff
                wireframeColor: [0.0, 0.35, 0.85],
                modelColor: [0.12, 0.42, 0.88],
                btnBg: 'rgba(248, 250, 252, 0.95)',
                btnColor: '#0f172a',
                btnBorder: '#cbd5e1',
                footerBg: 'rgba(248, 250, 252, 0.92)',
                footerColor: '#475569',
                footerBorder: 'rgba(203, 213, 225, 0.8)'
            }
        };

        var themeKeys = ['light', 'slate', 'white'];
        var currentThemeKey = localStorage.getItem('oqc_3d_bg_theme') || 'light';
        if (!THEMES[currentThemeKey]) currentThemeKey = 'light';

        // Create overlay UI bar
        var ui = document.createElement('div');
        ui.style.position = 'absolute';
        ui.style.top = '12px';
        ui.style.right = '12px';
        ui.style.display = 'flex';
        ui.style.gap = '6px';
        ui.style.zIndex = '10';

        var btnReset = document.createElement('button');
        btnReset.className = 'btn-secondary py-1 px-2.5 text-xs font-semibold rounded-md shadow-sm transition-all';
        btnReset.innerHTML = '🔄 Reset View';

        var btnWire = document.createElement('button');
        btnWire.className = 'btn-secondary py-1 px-2.5 text-xs font-semibold rounded-md shadow-sm transition-all';
        btnWire.innerHTML = '📐 Wireframe';

        var btnTheme = document.createElement('button');
        btnTheme.className = 'btn-secondary py-1 px-2.5 text-xs font-semibold rounded-md shadow-sm transition-all';

        function updateUiThemeStyles() {
            var th = THEMES[currentThemeKey] || THEMES.light;
            [btnReset, btnWire, btnTheme].forEach(function (btn) {
                btn.style.backgroundColor = th.btnBg;
                btn.style.color = th.btnColor;
                btn.style.borderColor = th.btnBorder;
                btn.style.cursor = 'pointer';
            });
            btnTheme.innerHTML = '🎨 BG: ' + th.label;

            // Sync parent viewport background & footer bar if present
            var vp3d = document.getElementById('viewport-3d');
            if (vp3d) {
                vp3d.style.backgroundColor = 'rgb(' + Math.round(th.clearColor[0] * 255) + ',' + Math.round(th.clearColor[1] * 255) + ',' + Math.round(th.clearColor[2] * 255) + ')';
            }
            var fbar = document.getElementById('viewport-footer-bar');
            if (fbar) {
                fbar.style.backgroundColor = th.footerBg;
                fbar.style.color = th.footerColor;
                fbar.style.borderColor = th.footerBorder;
            }
        }

        updateUiThemeStyles();

        ui.appendChild(btnTheme);
        ui.appendChild(btnReset);
        ui.appendChild(btnWire);
        container.appendChild(ui);

        // State variables for 3D Camera & Model Controls
        var rotX = 0.5;
        var rotY = 0.8;
        var zoom = -5.0;
        var isDragging = false;
        var lastX = 0, lastY = 0;
        var isWireframe = false;

        btnReset.onclick = function () {
            rotX = 0.5;
            rotY = 0.8;
            zoom = -5.0;
            requestAnimationFrame(draw);
        };

        btnWire.onclick = function () {
            isWireframe = !isWireframe;
            requestAnimationFrame(draw);
        };

        btnTheme.onclick = function () {
            var idx = themeKeys.indexOf(currentThemeKey);
            currentThemeKey = themeKeys[(idx + 1) % themeKeys.length];
            localStorage.setItem('oqc_3d_bg_theme', currentThemeKey);
            updateUiThemeStyles();
            requestAnimationFrame(draw);
        };

        // Mouse Drag Rotation
        canvas.addEventListener('mousedown', function (e) {
            isDragging = true;
            lastX = e.clientX;
            lastY = e.clientY;
        });

        window.addEventListener('mouseup', function () {
            isDragging = false;
        });

        canvas.addEventListener('mousemove', function (e) {
            if (!isDragging) return;
            var dx = e.clientX - lastX;
            var dy = e.clientY - lastY;
            rotY += dx * 0.01;
            rotX += dy * 0.01;
            lastX = e.clientX;
            lastY = e.clientY;
            requestAnimationFrame(draw);
        });

        // Mouse Wheel Zooming
        canvas.addEventListener('wheel', function (e) {
            e.preventDefault();
            zoom += e.deltaY * 0.005;
            if (zoom > -2.0) zoom = -2.0;
            if (zoom < -15.0) zoom = -15.0;
            requestAnimationFrame(draw);
        }, { passive: false });

        // Touch Controls
        canvas.addEventListener('touchstart', function (e) {
            if (e.touches.length === 1) {
                isDragging = true;
                lastX = e.touches[0].clientX;
                lastY = e.touches[0].clientY;
            }
        });

        canvas.addEventListener('touchmove', function (e) {
            if (isDragging && e.touches.length === 1) {
                var dx = e.touches[0].clientX - lastX;
                var dy = e.touches[0].clientY - lastY;
                rotY += dx * 0.01;
                rotX += dy * 0.01;
                lastX = e.touches[0].clientX;
                lastY = e.touches[0].clientY;
                requestAnimationFrame(draw);
            }
        });

        canvas.addEventListener('touchend', function () {
            isDragging = false;
        });

        // Shaders
        var vsSource = `
            attribute vec3 aPosition;
            attribute vec3 aNormal;
            uniform mat4 uMVMatrix;
            uniform mat4 uPMatrix;
            varying vec3 vNormal;
            varying vec3 vPosition;
            void main(void) {
                vec4 pos = uMVMatrix * vec4(aPosition, 1.0);
                vPosition = pos.xyz;
                vNormal = mat3(uMVMatrix) * aNormal;
                gl_Position = uPMatrix * pos;
            }
        `;

        var fsSource = `
            precision mediump float;
            varying vec3 vNormal;
            varying vec3 vPosition;
            uniform vec3 uColor;
            uniform bool uWireframe;
            void main(void) {
                if (uWireframe) {
                    gl_FragColor = vec4(0.2, 0.6, 1.0, 1.0);
                    return;
                }
                vec3 normal = normalize(vNormal);
                vec3 lightDir = normalize(vec3(1.0, 2.0, 3.0));
                float diff = max(dot(normal, lightDir), 0.25);
                vec3 ambient = uColor * 0.4;
                vec3 diffuse = uColor * diff * 0.75;
                gl_FragColor = vec4(ambient + diffuse, 1.0);
            }
        `;

        function createShader(gl, type, source) {
            var shader = gl.createShader(type);
            gl.shaderSource(shader, source);
            gl.compileShader(shader);
            return shader;
        }

        var vertShader = createShader(gl, gl.VERTEX_SHADER, vsSource);
        var fragShader = createShader(gl, gl.FRAGMENT_SHADER, fsSource);
        var program = gl.createProgram();
        gl.attachShader(program, vertShader);
        gl.attachShader(program, fragShader);
        gl.linkProgram(program);
        gl.useProgram(program);

        var aPosition = gl.getAttribLocation(program, "aPosition");
        var aNormal = gl.getAttribLocation(program, "aNormal");
        var uMVMatrix = gl.getUniformLocation(program, "uMVMatrix");
        var uPMatrix = gl.getUniformLocation(program, "uPMatrix");
        var uColor = gl.getUniformLocation(program, "uColor");
        var uWireframe = gl.getUniformLocation(program, "uWireframe");

        // Generate 3D Part Model Geometry (Chamfered Mechanical CAD Part)
        var vertices = [];
        var normals = [];
        var indices = [];

        function addBox(x, y, z, w, h, d, nx, ny, nz) {
            // Simplified CAD Part Box Mesh Generator
            var hw = w / 2, hh = h / 2, hd = d / 2;
            var faces = [
                // Front
                { pos: [x - hw, y - hh, z + hd, x + hw, y - hh, z + hd, x + hw, y + hh, z + hd, x - hw, y + hh, z + hd], norm: [0, 0, 1] },
                // Back
                { pos: [x + hw, y - hh, z - hd, x - hw, y - hh, z - hd, x - hw, y + hh, z - hd, x + hw, y + hh, z - hd], norm: [0, 0, -1] },
                // Top
                { pos: [x - hw, y + hh, z + hd, x + hw, y + hh, z + hd, x + hw, y + hh, z - hd, x - hw, y + hh, z - hd], norm: [0, 1, 0] },
                // Bottom
                { pos: [x - hw, y - hh, z - hd, x + hw, y - hh, z - hd, x + hw, y - hh, z + hd, x - hw, y - hh, z + hd], norm: [0, -1, 0] },
                // Right
                { pos: [x + hw, y - hh, z + hd, x + hw, y - hh, z - hd, x + hw, y + hh, z - hd, x + hw, y + hh, z + hd], norm: [1, 0, 0] },
                // Left
                { pos: [x - hw, y - hh, z - hd, x - hw, y - hh, z + hd, x - hw, y + hh, z + hd, x - hw, y + hh, z - hd], norm: [-1, 0, 0] }
            ];

            faces.forEach(function (f) {
                var baseIdx = vertices.length / 3;
                for (var i = 0; i < 4; i++) {
                    vertices.push(f.pos[i * 3], f.pos[i * 3 + 1], f.pos[i * 3 + 2]);
                    normals.push(f.norm[0], f.norm[1], f.norm[2]);
                }
                indices.push(baseIdx, baseIdx + 1, baseIdx + 2, baseIdx, baseIdx + 2, baseIdx + 3);
            });
        }

        // Build Multi-Component Industrial Part CAD Mesh
        addBox(0, 0, 0, 2.2, 0.5, 1.6);      // Base plate
        addBox(0, 0.4, 0, 1.4, 0.6, 1.2);    // Upper body
        addBox(-0.6, 0.8, 0, 0.4, 0.4, 0.4);  // Left boss
        addBox(0.6, 0.8, 0, 0.4, 0.4, 0.4);   // Right boss

        var vBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, vBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);

        var nBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, nBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(normals), gl.STATIC_DRAW);

        var iBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, iBuffer);
        gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);

        // Matrix Helpers
        function perspective(fovy, aspect, near, far) {
            var f = 1.0 / Math.tan(fovy / 2);
            var nf = 1 / (near - far);
            return [
                f / aspect, 0, 0, 0,
                0, f, 0, 0,
                0, 0, (far + near) * nf, -1,
                0, 0, (2 * far * near) * nf, 0
            ];
        }

        function draw() {
            var width = container.clientWidth;
            var height = container.clientHeight;
            canvas.width = width;
            canvas.height = height;

            var activeTheme = THEMES[currentThemeKey] || THEMES.light;
            var cc = activeTheme.clearColor;

            gl.viewport(0, 0, width, height);
            gl.clearColor(cc[0], cc[1], cc[2], cc[3]);
            gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
            gl.enable(gl.DEPTH_TEST);

            var pMatrix = perspective(Math.PI / 4, width / height, 0.1, 100.0);

            // MV Matrix calculations
            var c = Math.cos(rotX), s = Math.sin(rotX);
            var cy = Math.cos(rotY), sy = Math.sin(rotY);

            var mvMatrix = [
                cy, s * sy, -c * sy, 0,
                0, c, s, 0,
                sy, -s * cy, c * cy, 0,
                0, 0, zoom, 1
            ];

            gl.useProgram(program);

            gl.bindBuffer(gl.ARRAY_BUFFER, vBuffer);
            gl.vertexAttribPointer(aPosition, 3, gl.FLOAT, false, 0, 0);
            gl.enableVertexAttribArray(aPosition);

            gl.bindBuffer(gl.ARRAY_BUFFER, nBuffer);
            gl.vertexAttribPointer(aNormal, 3, gl.FLOAT, false, 0, 0);
            gl.enableVertexAttribArray(aNormal);

            gl.uniformMatrix4fv(uPMatrix, false, new Float32Array(pMatrix));
            gl.uniformMatrix4fv(uMVMatrix, false, new Float32Array(mvMatrix));

            var mc = activeTheme.modelColor;
            gl.uniform3f(uColor, mc[0], mc[1], mc[2]);
            gl.uniform1i(uWireframe, isWireframe ? 1 : 0);

            gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, iBuffer);

            var mode = isWireframe ? gl.LINES : gl.TRIANGLES;
            gl.drawElements(mode, indices.length, gl.UNSIGNED_SHORT, 0);
        }

        // Resize Listener
        window.addEventListener('resize', function () {
            requestAnimationFrame(draw);
        });

        // Initial Draw
        requestAnimationFrame(draw);
    }

    global.OQC3DViewer = OQC3DViewer;
})(window);
